INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (522, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Ovo de Páscoa literal no topo da torre de rádio', 'Suba a torre de rádio mais alta de Vice-Dale (~6–7 min), pegue um ovo pintado no ninho e jogue lá de cima: cutscene do ovo caindo num corretor. Daqui sai um BASE jump.', -41.92243, 0.33208, NULL, NULL, '{\"region\":\"perto de West Vice-Dale County\",\"source_category\":\"easter\",\"source_coords\":{\"x\":489.62,\"y\":743.08},\"breadcrumb\":\"West Vice-Dale County › Vice-Dale County\",\"precision\":\"ponto\",\"confidence\":\"c\",\"source_ref\":\"GameSpot — o ovo de Páscoa literal\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (523, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Abdução por OVNI (troféu \"The Truth Is Out There\")', 'Estrada de terra a noroeste do Starlet Motel (Gellhorn), a leste de Port Gellhorn, depois do Cap. 1 e das 2h da manhã, sem o parceiro: siga o carro com luzes piscando até a mata, salve a vítima e pegue o carro dela. Dá o troféu secreto; depois o OVNI ataca você.', -67.14046, 24.68171, NULL, NULL, '{\"region\":\"perto de Gellhorn\",\"source_category\":\"easter\",\"source_coords\":{\"x\":342,\"y\":596},\"breadcrumb\":\"Gellhorn › Port Gellhorn › Kelly County\",\"precision\":\"ponto\",\"confidence\":\"c\",\"source_ref\":\"WikiGTAVI — easter eggs do dia 1\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (524, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Bigfoot / Skunk Ape (Cottonmouth Lake)', 'Ao sul do Cottonmouth Lake (abaixo de Hamlet): ele aparece comendo um cervo; siga com o Focus Mode até uma efígie fedorenta que te nocauteia. Sem requisito de missão.', -36.06304, -47.64514, NULL, NULL, '{\"region\":\"perto de Pelican Valley\",\"source_category\":\"easter\",\"source_coords\":{\"x\":523.1,\"y\":1067.9},\"breadcrumb\":\"Pelican Valley › Grassrivers › Mariana County\",\"precision\":\"ponto\",\"confidence\":\"c\",\"source_ref\":\"Beebom — onde achar o Bigfoot\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (525, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Bigfoot / Skunk Ape (Gambit Bay)', 'Do outro lado de Gambit Bay a partir da casa do Jason: pegue o barco até a estrada sem saída da península; o Focus Mode mostra os sons.', -32.87611, -47.99876, NULL, NULL, '{\"region\":\"perto de Key Lento\",\"source_category\":\"easter\",\"source_coords\":{\"x\":541.8,\"y\":1070.7},\"breadcrumb\":\"Key Lento › Leonida Keys › Mariana County\",\"precision\":\"ponto\",\"confidence\":\"c\",\"source_ref\":\"PC Gamer — Bigfoot (Skunk Ape)\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (526, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Bigfoot / Skunk Ape (sul de Watson Bay)', 'Segundo ponto de avistamento relatado.', -54.69308, -35.80854, NULL, NULL, '{\"region\":\"perto de Watson Bay\",\"source_category\":\"easter\",\"source_coords\":{\"x\":414,\"y\":975},\"breadcrumb\":\"Watson Bay › Mariana County\",\"precision\":\"ponto\",\"confidence\":\"r\",\"source_ref\":\"Beebom — onde achar o Bigfoot\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (527, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Bigfoot / Skunk Ape (Boone Speedway)', 'Ao sul do Pay \'n\' Spray ao lado do Boone Speedway; rosnado audível de longe.', -31.91267, -37.34594, NULL, NULL, '{\"region\":\"perto de Pelican Valley\",\"source_category\":\"easter\",\"source_coords\":{\"x\":547.7,\"y\":984},\"breadcrumb\":\"Pelican Valley › Grassrivers › Mariana County\",\"precision\":\"ponto\",\"confidence\":\"r\",\"source_ref\":\"The Big Lead — caça ao criptídeo\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (528, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Missões do Kirk: \"Search for the Skunk Ape\"', 'Caçador de criptídeos (\"Skunk Apeology 101\"); ligue para o Kirk no 461-555-0139. O Skunk Ape, apelidado de Mr. Mangrove, aparece mais na estrada a leste do Cottonmouth Lake, rumo a Gambit Bay; investigar a árvore-efígie faz o protagonista desmaiar.', -45.30263, -32.18042, NULL, NULL, '{\"region\":\"Pelican River\",\"source_category\":\"easter\",\"source_coords\":{\"x\":469.2,\"y\":947.95},\"breadcrumb\":\"Pelican River › Pelican Valley › Grassrivers › Mariana County\",\"precision\":\"bairro\",\"confidence\":\"c\",\"source_ref\":\"OutputLag — Skunk Ape e Kirk\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (529, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Cool Dog no jet ski / Ilha dos Cachorros', 'Mais fácil em Gambit Bay: saia de barco do cais do Jason, pule na água e nade para longe. Em uns 5 minutos um cachorro de óculos num jet ski te resgata e leva a uma ilha cheia de cães. Jogue a bolinha, siga o cachorro e ele desenterra uma carteira com cerca de US$ 1.200.', -29.43245, -48.63128, NULL, NULL, '{\"region\":\"perto de Key Lento\",\"source_category\":\"easter\",\"source_coords\":{\"x\":562,\"y\":1076},\"breadcrumb\":\"Key Lento › Leonida Keys › Mariana County\",\"precision\":\"ponto\",\"confidence\":\"c\",\"source_ref\":\"GTA Zone — easter eggs e locais (papagaio, Lucky Dog, monumento)\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (530, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Apartamento do Dexter (Trinity Apartments)', 'Ponta norte de Washington Island, entre os ícones do Pay \'n\' Spray e da Vice Beach Top Fun Drones: prédio azul-claro com escada cilíndrica. O apartamento é a porta de canto no fim da passarela do 2º andar (trancada). Kit de ferramentas e seringa no telhado, barco parecido com o \"Slice of Life\" no cais (dá para roubar) e sacos de lixo no fundo do mar ali perto (mergulho).', 15.81627, 24.87474, NULL, NULL, '{\"region\":\"perto de Washington Island\",\"source_category\":\"easter\",\"source_coords\":{\"x\":829,\"y\":586},\"breadcrumb\":\"Washington Island › Vice Beach › Vice City › Vice-Dale County\",\"precision\":\"ponto\",\"confidence\":\"c\",\"source_ref\":\"Dexerto — apartamento do Dexter\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (531, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Laboratório de caranguejos (Pelican Valley Outpost)', 'Ligue a energia na lateral da casa, leia a senha no chão (CLEAVES), cofre: pista \"double success\", espécime 0036 (há guia citando 0072). Código da doca: 0212. Prêmio: SMG Crabshack VF5.', -46.87011, -41.59967, NULL, NULL, '{\"region\":\"perto de Gullet Marsh\",\"source_category\":\"easter\",\"source_coords\":{\"x\":459.8,\"y\":1018.4},\"breadcrumb\":\"Gullet Marsh › Pelican Valley › Grassrivers › Mariana County\",\"precision\":\"ponto\",\"confidence\":\"c\",\"source_ref\":\"The Big Lead — códigos do posto de pesquisa\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (532, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Casa da foto de San Andreas (casa do OVNI em Belville)', 'É a casa da foto misteriosa do bar Lil\' Probe\'Inn em GTA San Andreas: Definitive Edition (2021). Na garagem, anotações de um morador que acha que vive num videogame: não consegue comprar passagem para Los Santos nem sair do estado e repara em NPCs repetidos e gente atravessando paredes. Também tem um meteorito para vender.', -15.04115, 31.08353, NULL, NULL, '{\"region\":\"Belville\",\"source_category\":\"easter\",\"source_coords\":{\"x\":647.97,\"y\":547.36},\"breadcrumb\":\"Belville › Leonard County\",\"precision\":\"bairro\",\"confidence\":\"c\",\"source_ref\":\"VGTimes — casa da foto de San Andreas\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
