INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (944, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Carro de Velozes e Furiosos: Eclipse verde do Brian O\'Conner (Paul Walker)', 'Easter egg de The Fast and the Furious (Velozes e Furiosos, 2001). No jogo se chama Maibatsu \'97 Penumbra FF, com placa \"HAD YOU\". Fica na garagem de uma casa branca moderna no centro de Vespucci Island (Rialto Causeway). Caminho: suba por Vice-Dale até a ponte das Rialto Islands, atravesse Catalan Island e pegue a ponte para Vespucci. Pule a cerca viva e entre pela porta lateral da garagem; isso dispara um alarme que precisa ser desligado. Abra o portão pelo painel ao lado, quebre o vidro ou use o app Slim Jim e faça ligação direta. Dá para pegar logo no começo; para guardar, registre num Pay \'n\' Spray (registro liberado no Cap. 2, US$ 6.750).', 6.82507, 12.64875, NULL, NULL, '{\"region\":\"perto de Vespucci Island\",\"source_category\":\"easter\",\"source_coords\":{\"x\":776,\"y\":664},\"breadcrumb\":\"Vespucci Island › Vice City › Vice-Dale County\",\"precision\":\"ponto\",\"confidence\":\"c\",\"source_ref\":\"Insider Gaming — Eclipse de Paul Walker (Velozes e Furiosos)\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (945, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Cobra no porta-malas do Eclipse (referência a Toy Story)', 'Abra o porta-malas do carro de Velozes e Furiosos antes de sair com ele: uma cobra salta e ataca, piada com o \"tem uma cobra na minha bota\" do Woody.', 6.94460, 12.54834, NULL, NULL, '{\"region\":\"perto de Vespucci Island\",\"source_category\":\"easter\",\"source_coords\":{\"x\":776.7,\"y\":664.6},\"breadcrumb\":\"Vespucci Island › Vice City › Vice-Dale County\",\"precision\":\"ponto\",\"confidence\":\"c\",\"source_ref\":\"Techtroduce — Eclipse, alarme e cobra de Toy Story\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (946, (SELECT id FROM poi_categories WHERE slug = 'veiculos-oficinas' LIMIT 1), 'Maibatsu \'97 Penumbra FF (Eclipse de Velozes e Furiosos)', 'Réplica do Mitsubishi Eclipse verde do primeiro filme. Um dos carros mais rápidos do começo do jogo (velocidade 7,2; aceleração 7,6), mas frágil em batidas. Passo a passo no easter egg do mesmo lugar.', 6.70553, 12.74913, NULL, NULL, '{\"region\":\"perto de Vespucci Island\",\"source_category\":\"veiculo\",\"source_coords\":{\"x\":775.3,\"y\":663.4},\"breadcrumb\":\"Vespucci Island › Vice City › Vice-Dale County\",\"precision\":\"ponto\",\"confidence\":\"c\",\"source_ref\":\"GamesHorizon — passo a passo do Eclipse\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (947, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Papagaio falante da Three Sheets Liquor (dinheiro grátis)', 'Depois do recado do rum da Shirley, volte à Three Sheets Liquor e pule a cerca lateral (não a de trás do balcão). Vença os capangas, ache o papagaio vermelho na gaiola e confira a grade ao lado do gerador: mais de US$ 1.300.', -27.64146, -53.63237, NULL, NULL, '{\"region\":\"Key Lento\",\"source_category\":\"easter\",\"source_coords\":{\"x\":572.38,\"y\":1123.32},\"breadcrumb\":\"Key Lento › Leonida Keys › Mariana County\",\"precision\":\"bairro\",\"confidence\":\"r\",\"source_ref\":\"GTA Zone — easter eggs e locais (papagaio, Lucky Dog, monumento)\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (948, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Monumento da Supremacia Leonidense (mistério estilo Mount Chiliad)', 'Quatro cavalos com esculturas que parecem mapas estelares, um deles com um cone de trânsito na cabeça; a placa fala em \"Leonidafication\". Perto dele o controle vibra e bipa num padrão que pode ser código Morse. Fica junto à SR-73, no norte do Manifest Canyon, ao norte de Port Gellhorn, e também é um ponto do WAiNK. Ainda sem solução.', -63.31073, 48.96883, NULL, NULL, '{\"region\":\"perto de Manifest Canyon\",\"source_category\":\"easter\",\"source_coords\":{\"x\":365,\"y\":412},\"breadcrumb\":\"Manifest Canyon › North Kelly County › Kelly County\",\"precision\":\"ponto\",\"confidence\":\"r\",\"source_ref\":\"Push Square — Monumento da Supremacia Leonidense (WAiNK)\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (949, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Bigfoot / Skunk Ape (Gullet Marsh)', 'Local apontado pela GameSpot para o encontro com o Skunk Ape; outros guias citam o sul do Cottonmouth Lake.', -39.30735, -36.85179, NULL, NULL, '{\"region\":\"Gullet Marsh\",\"source_category\":\"easter\",\"source_coords\":{\"x\":504.3,\"y\":981.09},\"breadcrumb\":\"Gullet Marsh › Pelican Valley › Grassrivers › Mariana County\",\"precision\":\"bairro\",\"confidence\":\"r\",\"source_ref\":\"GTA Zone — easter eggs e locais (papagaio, Lucky Dog, monumento)\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (950, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'OVNI desenhado no mapa da Collector\'s Box (Breakwater Quarry)', 'O pôster do mapa da edição de colecionador mostra um OVNI sobre a pedreira. A Rockstar não confirmou nenhum evento ali; por enquanto é só um desenho.', -53.58610, -8.48717, NULL, NULL, '{\"region\":\"perto de North Mariana County\",\"source_category\":\"easter\",\"source_coords\":{\"x\":421,\"y\":797},\"breadcrumb\":\"North Mariana County › Mariana County\",\"precision\":\"ponto\",\"confidence\":\"p\",\"source_ref\":\"GamesCard — OVNI no mapa da Collector\'s Box\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
INSERT INTO pois (id, category_id, title, description, coord_x, coord_y, image_url, panorama_url, metadata, status) VALUES (951, (SELECT id FROM poi_categories WHERE slug = 'easter-eggs' LIMIT 1), 'Cesta de basquete sob casa de palafita', 'Um dos primeiros achados virais do lançamento: o primeiro basquete jogável da série desde San Andreas.', -47.85395, -58.38341, NULL, NULL, '{\"region\":\"Leonida Keys\",\"source_category\":\"easter\",\"source_coords\":{\"x\":453.58,\"y\":1176.12},\"breadcrumb\":\"Leonida Keys › Mariana County\",\"precision\":\"regiao\",\"confidence\":\"r\",\"source_ref\":\"GTA6info Wiki — Easter Eggs\"}', 'PUBLISHED') ON DUPLICATE KEY UPDATE category_id = VALUES(category_id), title = VALUES(title), description = VALUES(description), coord_x = VALUES(coord_x), coord_y = VALUES(coord_y), metadata = VALUES(metadata), status = VALUES(status);
